"""Hermes native slash-command adapter generated by Hermes Universal Plugin Port.

FIXED TEMPLATE: this file is copied verbatim (never model-generated) and its
SHA-256 is recorded in the Capability Passport.

Registration (v0.4.2, review R1/R2): NOTHING is registered by default. A command
is registered only if ALL of these hold:
  * its manifest outcome is fully adapted (never PARTIAL/BLOCKED/UNSUPPORTED);
  * an operator approval record exists OUTSIDE this folder, at
    <this folder>/../../universal-port-approvals/<this folder name>.json
    (installed: HERMES_HOME/universal-port-approvals/<name>.json);
  * that record's adapter_package_sha256 equals the digest of EVERY file in this
    folder (manifest included), so a manifest-only edit invalidates it;
  * the record lists the command (source name, source sha256, Hermes name).
This is an integrity binding, not cryptographic authentication: whoever can
rewrite both this folder and the approval record can defeat it.

v0.4.3 (review P0): checks in THIS file cannot protect against a planted
__pycache__/*.pyc or extension module, because Python may execute that instead
of this source. The external pre-import gate (pre_import_gate.py in Universal
Port, via `repair_cli.py verify-adapter` / `stage`) must pass right before any
import, and the folder must contain no bytecode cache at all.

On each call a registered handler:

  1. re-verifies the SHA-256 of the original command file and of the bundled
     renderer against ADAPTER_MANIFEST.json (tamper => refuse, nothing sent);
  2. renders the ORIGINAL command body with documented Claude Code `$ARGUMENTS`
     semantics (claude_command.render) after replacing `!` shell injections with
     Claude Code's documented "disabled by policy" placeholder;
  3. queues the rendered prompt as ONE user message via ctx.inject_message.

It never runs shell commands, never calls tools or models itself, never writes
files, and never changes Hermes approvals or tool permissions. Status: generated
and statically checked; NOT runtime-verified on a real Hermes unless the
Capability Passport says so.
"""
import hashlib
import json
from pathlib import Path

from . import claude_command as _cc

_HERE = Path(__file__).resolve().parent
_APPROVAL_PATH = _HERE.parent.parent / 'universal-port-approvals' / (_HERE.name + '.json')
_APPROVAL_SCHEMA = 'universal-port.operator-approval/1'
_HEADER = '[Ported Claude Code command /{source} via Hermes adapter /{target}; source sha256 {sha12}]\n'


def _sha_file(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _load_manifest():
    manifest = json.loads((_HERE / 'ADAPTER_MANIFEST.json').read_text(encoding='utf-8'))
    if manifest.get('schema') != 'universal-port.command-adapter/1':
        raise ValueError('Unknown adapter manifest schema')
    return manifest


def _verify(manifest, entry):
    if _sha_file(_HERE / 'claude_command.py') != manifest['renderer_sha256']:
        raise ValueError('renderer changed after verification')
    path = (_HERE / 'commands' / entry['file']).resolve()
    if path.parent != (_HERE / 'commands').resolve() or path.is_symlink():
        raise ValueError('command file path escapes adapter')
    raw = path.read_bytes()
    if hashlib.sha256(raw).hexdigest() != entry['source_sha256']:
        raise ValueError('original command changed after verification')
    return raw.decode('utf-8')


def build_message(manifest, entry, raw_args):
    """Pure function used by the handler and by offline verification."""
    text = _verify(manifest, entry)
    _meta, body, _unparsed = _cc.parse_frontmatter(text)
    body = _cc.disable_shell_injections(body)
    rendered = _cc.render(body, raw_args.strip(), entry.get('argument_names') or [])
    header = _HEADER.format(source=entry['source_name'], target=entry['hermes_command'],
                            sha12=entry['source_sha256'][:12])
    return header + rendered['text']


def make_handler(ctx, manifest, entry):
    def handler(raw_args=''):
        try:
            message = build_message(manifest, entry, raw_args or '')
        except _cc.ArgumentRenderRefused as exc:
            return 'NOT SENT: /' + entry['hermes_command'] + ' arguments refused (' + str(exc) + ').'
        except (ValueError, OSError, UnicodeError) as exc:
            return 'NOT SENT: adapter integrity check failed (' + type(exc).__name__ + ': ' + str(exc)[:120] + ').'
        try:
            delivered = ctx.inject_message(message, role='user')
        except Exception as exc:  # report, never retry automatically
            return 'NOT SENT: Hermes inject_message raised ' + type(exc).__name__ + '.'
        if delivered is not True:
            return ('NOT SENT: Hermes refused the message (in gateway/TUI sessions this requires '
                    'plugins.entries.<plugin>.allow_gateway_injection: true, which this adapter never sets).')
        return 'Queued /' + entry['hermes_command'] + ' (' + str(len(message)) + ' chars) as a user message.'
    return handler


# v0.4.1 (review P0-1): fail closed. Only fully adapted outcomes are eligible;
# PARTIAL_REVIEW_REQUIRED, BLOCKED_UNSAFE, UNSUPPORTED, PENDING or any unknown
# value are listed in the manifest but never registered.
REGISTRABLE_OUTCOMES = frozenset({'ADAPTED_STATICALLY', 'ADAPTED_RUNTIME_VERIFIED', 'DIRECT_EQUIVALENT_VERIFIED'})


def package_sha256(folder=None):
    """Digest of EVERY file in the adapter folder (path + content), no exclusions (v0.4.3)."""
    folder = Path(folder) if folder is not None else _HERE
    h = hashlib.sha256()
    # Explicit POSIX-string order: WindowsPath sorts case-insensitively, which would change the digest.
    for f in sorted(folder.rglob('*'), key=lambda x: x.relative_to(folder).as_posix()):
        if f.is_symlink():
            raise ValueError('symlink inside adapter package')
        if f.is_file():
            h.update(f.relative_to(folder).as_posix().encode() + b'\0' + hashlib.sha256(f.read_bytes()).digest())
    return h.hexdigest()


def _load_approval():
    """The operator approval record, or None when no approval exists (the default)."""
    if not _APPROVAL_PATH.is_file():
        return None
    if _APPROVAL_PATH.is_symlink():
        raise ValueError('approval record must not be a symlink')
    approval = json.loads(_APPROVAL_PATH.read_text(encoding='utf-8'))
    if approval.get('schema') != _APPROVAL_SCHEMA or approval.get('adapter') != _HERE.name:
        raise ValueError('approval record does not belong to this adapter')
    return approval


def register(ctx):
    manifest = _load_manifest()
    if _sha_file(_HERE / 'claude_command.py') != manifest['renderer_sha256']:
        raise ValueError('renderer changed after verification')
    approval = _load_approval()
    if approval is None:
        return  # v0.4.2 (review R1): no operator approval -> nothing is registered
    if approval.get('adapter_package_sha256') != package_sha256():
        raise ValueError('adapter folder differs from the approved digest; nothing registered (a __pycache__ '
                         'counts: run Hermes with PYTHONDONTWRITEBYTECODE=1 from a freshly staged folder)')
    approved = {(a.get('source_name'), a.get('source_sha256'), a.get('hermes_command'))
                for a in approval.get('approved', [])}
    for entry in manifest.get('commands', []):
        if entry.get('outcome') not in REGISTRABLE_OUTCOMES:
            continue
        if (entry.get('source_name'), entry.get('source_sha256'), entry.get('hermes_command')) not in approved:
            continue
        _verify(manifest, entry)
        ctx.register_command(entry['hermes_command'], handler=make_handler(ctx, manifest, entry),
                             description=(entry.get('description') or 'Ported Claude Code command')[:200],
                             args_hint=entry.get('args_hint') or '')
